let dayRouteMap,dayRouteLayer,dayRouteLoading,dayRouteCoordinates,dayRouteRequest=0;
function loadDayRoute(){
 if(dayRouteLoading)return dayRouteLoading;
 dayRouteLoading=Promise.all([fetch('vendor/route-coordinates.json').then(r=>{if(!r.ok)throw Error();return r.json()}),new Promise((resolve,reject)=>{const css=document.createElement('link');css.rel='stylesheet';css.href='vendor/leaflet.css';css.onload=resolve;css.onerror=reject;document.head.append(css)}),new Promise((resolve,reject)=>{if(window.L)return resolve();const js=document.createElement('script');js.src='vendor/leaflet.js';js.onload=resolve;js.onerror=reject;document.head.append(js)})]).then(([coords])=>{dayRouteCoordinates=coords}).catch(e=>{dayRouteLoading=null;throw e});return dayRouteLoading;
}
async function openDayRoute(day){
 day=day||currentDay;const request=++dayRouteRequest;const dialog=document.getElementById('day-route-dialog');if(!dialog.open)dialog.showModal();document.querySelectorAll('[data-route-day]').forEach(b=>b.classList.toggle('active',Number(b.dataset.routeDay)===day));const status=document.getElementById('route-status');status.textContent='正在載入今日地圖…';
 try{await loadDayRoute();if(request!==dayRouteRequest||!dialog.open)return;
 if(!dayRouteMap){dayRouteMap=L.map('day-route-map');L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'}).addTo(dayRouteMap);dayRouteLayer=L.layerGroup().addTo(dayRouteMap)}
 dayRouteLayer.clearLayers();const list=document.getElementById('day-route-list');list.replaceChildren();const points=[];let missing=0;const cards=[...document.querySelectorAll('#day-'+day+' .card[data-map-place-input]')];
 cards.forEach((card,i)=>{const raw=card.dataset.mapPlaceInput;const coords=dayRouteCoordinates[raw];const title=card.querySelector('.item-title')?.textContent.trim()||card.dataset.mapPlaceValue;const time=card.querySelector('.time-badge')?.textContent.trim()||'';const row=document.createElement('div');row.className='route-stop';const selectRow=()=>{list.querySelectorAll('.route-stop').forEach(el=>el.classList.remove('route-stop-selected'));row.classList.add('route-stop-selected');const top=row.getBoundingClientRect().top-list.getBoundingClientRect().top+list.scrollTop;list.scrollTo({top:Math.max(0,top-8),behavior:'smooth'});};const button=document.createElement('button');button.textContent=(i+1)+' · '+title;row.append(button);const meta=document.createElement('small');meta.textContent=time+(coords?'':' · 尚未定位');row.append(meta);const nav=document.createElement('a');nav.textContent='Google Maps ↗';nav.href=/^https:\/\//.test(raw)?raw:'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(raw);nav.target='_blank';nav.rel='noopener';row.append(nav);const back=document.createElement('button');back.textContent='查看行程';back.style.fontSize='12px';back.onclick=()=>{dialog.close();switchDay(day,{auto:true});setTimeout(()=>card.scrollIntoView({behavior:'smooth',block:'center'}),80)};row.append(back);list.append(row);
 if(coords){points.push(coords);const popup=document.createElement('div');const label=document.createElement('b');label.textContent=(i+1)+' · '+title;popup.append(label,document.createElement('br'),document.createTextNode(time),document.createElement('br'),nav.cloneNode(true));const marker=L.marker(coords,{icon:L.divIcon({className:'route-number',html:String(i+1),iconSize:[30,30],iconAnchor:[15,15]})}).bindPopup(popup).addTo(dayRouteLayer);marker.on('click',selectRow);button.onclick=()=>{selectRow();dayRouteMap.setView(coords,16);marker.openPopup()};}else{missing++;button.onclick=()=>nav.click()}
 });
 if(points.length>1)L.polyline(points,{color:'#b97488',weight:3,dashArray:'7 9',opacity:.75}).addTo(dayRouteLayer);
 dayRouteMap.invalidateSize();const japan=points.filter(p=>p[1]>128);const bounds=japan.length?japan:points;if(bounds.length)dayRouteMap.fitBounds(bounds,{padding:[30,30],maxZoom:15});else dayRouteMap.setView([34.7,136.7],9);
 status.textContent='虛線表示行程順序，不是實際道路；點編號查看景點。'+(missing?' '+missing+' 個地點尚未定位，可由清單開啟 Google Maps。':'');
 }catch(e){status.textContent='地圖暫時無法載入，請確認網路後再點星期重試。'}
}
